import{_ as s,o as r,c as o,a3 as a}from"./chunks/framework.I6s8z2kk.js";const m=JSON.parse('{"title":"Roles and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"dev/conventions/permissions.md","filePath":"dev/conventions/permissions.md"}'),t={name:"dev/conventions/permissions.md"};function i(c,e,d,n,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h1><h2 id="one-guard-per-actor" tabindex="-1">One guard per actor <a class="header-anchor" href="#one-guard-per-actor" aria-label="Permalink to &quot;One guard per actor&quot;">​</a></h2><p>Client routes use <code>auth:client</code>, center users <code>auth:center_user</code> with <code>center.scope</code>, system users <code>auth:system_user</code>.</p><h2 id="system-users" tabindex="-1">System users <a class="header-anchor" href="#system-users" aria-label="Permalink to &quot;System users&quot;">​</a></h2><p>System users have roles made of <strong><code>SystemPermission</code></strong> values such as <code>centers.view_any</code>, <code>promotions.activate</code>, <code>fees.manage</code>, <code>payouts.manage</code>, <code>payouts.baseline</code> (set a migrated center&#39;s financial baseline), <code>analytics.view</code>, <code>legal_documents.manage</code>, <code>otps.create</code> (issue a login OTP for a client or center user) and <code>api_docs.view</code>.</p><ul><li>Add a new admin capability as a new <code>SystemPermission</code> case named <code>resource.action</code>.</li><li>Never edit or delete protected <code>SystemRole</code>s.</li><li>Every admin policy denies <strong>inactive</strong> system users in <code>before()</code>.</li></ul><h2 id="center-users" tabindex="-1">Center users <a class="header-anchor" href="#center-users" aria-label="Permalink to &quot;Center users&quot;">​</a></h2><p>Center users belong to centers through an assignment, and hold <strong><code>CenterUserPermission</code></strong> values:</p><table tabindex="0"><thead><tr><th>Group</th><th>Permissions</th></tr></thead><tbody><tr><td>Services, per type</td><td><code>services.recreation_riding.manage</code>, <code>services.visit.manage</code>, <code>services.event.manage</code>, <code>services.resort.manage</code>, <code>services.horse_care.manage</code>, <code>services.horse_service.manage</code>, <code>services.training.manage</code>, <code>services.membership.manage</code></td></tr><tr><td>Purchases, per type</td><td><code>purchases.&lt;type&gt;.view</code>, plus <code>purchases.view_prices</code>, <code>purchases.view_other_trainers</code>, <code>purchases.view_unassigned</code></td></tr><tr><td>Reservations</td><td><code>reservations.manage</code>, <code>reservations.edit</code></td></tr><tr><td>Other</td><td><code>users.manage</code>, <code>ratings.view</code>, <code>blocked_clients.manage</code>, <code>promotions.manage</code>, <code>analytics.view</code>, <code>payouts.view</code>, <code>purchases.export</code>, <code>clients.export</code></td></tr></tbody></table><p>The <strong>primary user</strong> (<code>is_primary</code>, role <code>owner</code>) implicitly holds every center permission, can never be modified, and must re-enter their password on <code>POST /centers/{center}/access</code>. Non-primary managers cannot modify themselves and can only grant permissions they hold. Removing a user revokes their center tokens; a user with no centers left is soft-deleted.</p><h2 id="shared-policies" tabindex="-1">Shared policies <a class="header-anchor" href="#shared-policies" aria-label="Permalink to &quot;Shared policies&quot;">​</a></h2><p>Policies for shared admin and center endpoints authorize <code>User|SystemUser</code>: center users by active assignment plus center permission, system users by <code>SystemPermission</code>.</p><p>Service authorization depends on the type: <code>Gate::authorize(&#39;manageServices&#39;, [$center, ServiceType::X])</code>. Trainers fall under Training. Center-wide blocks and gender periods need <code>manageAllServices</code>.</p><h2 id="purchase-visibility" tabindex="-1">Purchase visibility <a class="header-anchor" href="#purchase-visibility" aria-label="Permalink to &quot;Purchase visibility&quot;">​</a></h2><p>Non-primary center users see purchases through <code>CenterPurchaseVisibility</code>: the type&#39;s <code>purchases.{type}.view</code>, their own linked trainer always, other trainers&#39; only with <code>purchases.view_other_trainers</code>, and trainer-less items only with <code>purchases.view_unassigned</code>. Primary and system users see all.</p>',15)])])}const u=s(t,[["render",i]]);export{m as __pageData,u as default};
